71:         }
72:         let threshold = match self.options.jitter_filter_m {
73:             Some(t) if t > 0.0 => t,
74:             _ => return points.iter().collect(),
75:         };
76: 
77:         let mut out = Vec::with_capacity(points.len());
78:         out.push(&points[0]);
79: 
80:         for pt in &points[1..points.len() - 1] {
81:             let prev = out.last().unwrap();
82:             let d_lat = (pt.latitude - prev.latitude).abs() * 111_000.0;
83:             let d_lon = (pt.longitude - prev.longitude).abs() * 111_000.0 * pt.latitude.to_radians().cos().abs();
84:             let d_alt = (pt.altitude_msl - prev.altitude_msl).abs();
85:             let dist_3d = (d_lat * d_lat + d_lon * d_lon + d_alt * d_alt).sqrt();
86: 
87:             if dist_3d >= threshold {
88:                 out.push(pt);
89:             }
90:         }
91: 
92:         if points.len() > 1 {
93:             out.push(points.last().unwrap());
94:         }
